"""Class 8 Maths Ch 10 - Proportional Reasoning-2 (ratio, direct/inverse proportion, map scale, pie charts)."""
from c8m_u import *

SLUG, NAME, CHNO = "Proportional_Reasoning_2", "Proportional Reasoning-2", 10

def I(x):
    x = Fr(x); assert x.denominator == 1, x; return int(x)
def rat(a, b):
    k = gcd(a, b); return f"{a//k}:{b//k}"
def rat3(a, b, c):
    k = gcd(gcd(a, b), c); return f"{a//k}:{b//k}:{c//k}"
def combine(p, q, r, s):
    """a:b = p:q and b:c = r:s -> a:b:c"""
    L = lcm(q, r); return p * L // q, L, s * L // r
def ang(c, T): return Fr(c * 360, T)

