def pie_q(it):
    a, b, c, d, x1, x2, x3, x4 = it; T = x1 + x2 + x3 + x4
    return Q(f"The data of {T} students' choices is: {a} {x1}, {b} {x2}, {c} {x3}, {d} {x4}. Find the central angle of each sector for a pie chart and verify that the angles add to $360^\\circ$.",
             f"Angle per student $=360^\\circ\\div{T}={g(Fr(360,T))}^\\circ$ (1); {a}: {g(ang(x1,T))}°, {b}: {g(ang(x2,T))}° (2); {c}: {g(ang(x3,T))}°, {d}: {g(ang(x4,T))}° (1); sum $={g(ang(x1,T)+ang(x2,T)+ang(x3,T)+ang(x4,T))}^\\circ$ (1).", "1+2+1+1")
EASY_D = ([pie_q(it) for it in PIE_E]
          + [Q(f"A camp has food for {n} people for {d} days. If {m} more people join the camp, for how many days will the same food last?", f"Total food $={n}\\times{d}={n*d}$ person-days (2); people now $={n+m}$ (1); days $={n*d}\\div{n+m}={I(Fr(n*d,n+m))}$ (2).", "2+1+2") for n, d, m in [(20, 15, 10), (30, 12, 6), (24, 10, 6), (45, 8, 15), (36, 10, 24), (15, 16, 5)]])

