def cmpq(rs):
    vals = [Fr(a, b) for a, b in rs]; top = max(vals); assert vals.count(top) == 1
    w = rs[vals.index(top)]; others = [x for x in rs if x != w]
    return M4("Which of the following is the greatest ratio?", f"{w[0]}:{w[1]}", [f"{a}:{b}" for a, b in others], "Compare as fractions: " + ", ".join(f"${fr(a,b)}\\approx{float(Fr(a,b)):.3f}$" for a, b in rs))
